function articleSections(html){
 const hs=[...html.matchAll(/<h2\b[^>]*>[\s\S]*?<\/h2>/gi)];
 return hs.map((m,i)=>{
  const start=m.index+m[0].length,end=i+1<hs.length?hs[i+1].index:html.length;
  const raw=html.slice(start,end),tail=(raw.match(/(?:\s|<!--\s*ARTICLE_IMAGE_[123]\s*-->)*$/)||[''])[0];
  return {id:'section_'+i,heading:m[0].replace(/<[^>]*>/g,'').trim(),start,end:end-tail.length,body_html:raw.slice(0,raw.length-tail.length)};
 });
}

return $input.all().map((item,i)=>{
 const s=item.json,sections=articleSections(String(s.article?.content_html||''));
 s.review_section_options=['تحديد تلقائي من الملاحظات',...sections.map(x=>x.id+' | '+x.heading),'العنوان الرئيسي فقط','عنوان SEO فقط','وصف الميتا فقط','كل نص المقال'];
 return {json:s,...(item.binary?{binary:item.binary}:{}),pairedItem:{item:i}};
});

const s=JSON.parse(JSON.stringify($('Review Request Context').item.json)),d=$json.data||{};
if(!d['القرار']&&s.review_deadline&&Date.parse(s.review_deadline)<=Date.now()){s.decision='timeout';s.reason='انتهت مهلة المراجعة 48 ساعة دون قرار';return [{json:s}];}
if(s.review_deadline&&Date.parse(s.review_deadline)<Date.now())throw new Error('Expired review token');
if(d.review_token!==s.review_token)throw new Error('Stale or mismatched article revision');
const map={'موافقة':'approve','تعديل':'revise','رفض':'reject'};
s.decision=map[d['القرار']];if(!s.decision)throw new Error('Unknown decision');
s.feedback=String(d['ملاحظات التعديل']||'').trim();
const scope=String(d['نطاق التعديل']||'تعديل النص فقط').trim();
s.revision_scope=scope==='تعديل النص والصور'?'text_and_images':'text_only';
s.revision_target=String(d['القسم المطلوب تعديله']||'تحديد تلقائي من الملاحظات').trim();
if(s.decision==='revise'&&!s.feedback){s.decision='missing_feedback';s.reason='اكتب التعديلات المطلوبة في خانة الملاحظات.';}
return [{json:s}];
